// The logos of the languages GitHub reports, by GitHub's language name
// (linguist's: "TypeScript", "Jupyter Notebook", "Vim Script"). Each is the
// single 24 × 24 SVG path of a Simple Icons glyph (simple-icons 16.34.0,
// CC0-1.0 — https://simpleicons.org; the brands remain their owners'
// trademarks). Bundled, not fetched: the logos show offline and the phone never
// asks a third party for them. A language without an entry (C#, PowerShell —
// Simple Icons carries no logo for them) is drawn as a monogram instead.
//
// language-logos.test.ts checks every path against the installed simple-icons
// package, so an entry cannot drift from its source. To add a language, map
// its GitHub name to a Simple Icons slug here and copy the `d` of
// node_modules/simple-icons/icons/<slug>.svg — the test names any mismatch.

export interface LanguageLogo {
	/** The Simple Icons slug the path comes from (`icons/<slug>.svg`). */
	readonly slug: string;
	/** SVG path data in a 24 × 24 box. */
	readonly path: string;
}

